/**
 * Hugo Drip Reply Route — handles inbound replies to Hugo's autonomous drip emails.
 *
 * Processing pipeline:
 *   1. Receive inbound email (webhook from Gmail/Resend or Polsia inbox poll)
 *   2. Check auto-generated headers (CRITICAL — before Groq call)
 *   3. Auto-generated → archive/skip (NOT classified)
 *   4. Real reply → classify intent via Groq (interested / not_interested / question)
 *   5. Apply state change to lead (REPLIED / UNSUBSCRIBED / draft response)
 *   6. If interested → notify Obeid + log deal
 *   7. If question → generate draft response via Hugo's knowledge base
 *
 * Anti-loop: isAutoGenerated() MUST be called before classifyIntent().
 * Out-of-office autoresponders are NOT valid replies.
 */

const express = require('express');
const router = express.Router();
const { Pool } = require('pg');
const { requireAuth } = require('./auth');
const { isAutoGenerated } = require('../services/hugo-drip-resend');
const { classifyAndApply } = require('../services/hugo-drip-intent');
const { sendEmail } = require('../services/emailSender');
const { composeReply } = require('../services/emailComposer');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DATABASE_URL?.includes('localhost') ? false : { rejectUnauthorized: false },
});

// ─── POST /api/hugo/drip/inbound ────────────────────────────────────────────────
// Receives inbound emails from Hugo's inbox reader or direct webhook.
// Body: { leadId, from, subject, body_text, headers, inboundEmailId? }

router.post('/inbound', async (req, res) => {
  const { leadId, from, subject, body_text, headers, inboundEmailId } = req.body || {};

  if (!leadId || !body_text) {
    return res.status(400).json({ success: false, error: 'leadId and body_text required' });
  }

  try {
    // ── Step 1: Auto-reply filter (NON-NEGOTIABLE — check BEFORE Groq) ────
    const emailHeaders = headers || {};
    if (isAutoGenerated(emailHeaders)) {
      console.log(`[HugoDripReply] ⛔ Auto-generated reply skipped — lead ${leadId}`);
      return res.json({
        success: true,
        skipped: true,
        reason: 'auto_generated',
        message: 'Out-of-office autoresponders are not valid replies',
      });
    }

    // ── Step 2: Fetch lead context for Groq classification ─────────────────
    const leadRows = await pool.query(
      `SELECT l.id, l.name, l.email, l.service AS job_type,
              u.name AS operator_name
       FROM leads l
       LEFT JOIN users u ON l.operator_id = u.id
       WHERE l.id = $1`,
      [parseInt(leadId, 10)]
    );
    const lead = leadRows.rows[0];
    if (!lead) {
      return res.status(404).json({ success: false, error: 'Lead not found' });
    }

    // ── Step 3: Classify intent via Groq ───────────────────────────────────
    const context = {
      operatorId: lead.drip_operator_id || null,
      dripDay: null,
      leadName: lead.name,
      jobType: lead.job_type,
    };

    const intentResult = await classifyAndApply(body_text, lead.id, context);

    // ── Step 4: Respond based on intent ───────────────────────────────────
    if (intentResult.intent === 'interested') {
      // Already handled in onInterested() — just confirm
      return res.json({
        success: true,
        intent: 'interested',
        action: 'notified_obeid',
        message: 'Obeid notified, deal logged',
      });
    }

    if (intentResult.intent === 'not_interested') {
      return res.json({
        success: true,
        intent: 'not_interested',
        action: 'unsubscribed',
        message: 'Lead marked as unsubscribed, drip stopped',
      });
    }

    // ── Step 5: Question — generate draft response ──────────────────────────
    try {
      const draftResponse = await composeReply({
        leadData: lead,
        inboundEmail: { body: body_text },
        replyType: 'custom',
        tone: 'professional',
        operatorId: lead.drip_operator_id || null,
      });

      // Send draft to operator for approval (not auto-sent)
      const operatorEmail = lead.operator_name || 'founder';
      await pool.query(
        `INSERT INTO operator_emails
           (operator_id, from_address, subject, body_text, status, source)
         VALUES ($1, $2, $3, $4, 'draft', 'hugo_drip_question')`,
        [lead.drip_operator_id || null, from, `Re: ${subject}`, draftResponse]
      ).catch(() => {});

      return res.json({
        success: true,
        intent: 'question',
        action: 'draft_generated',
        draft: draftResponse,
        message: 'Draft response generated and sent to operator inbox for review',
      });
    } catch (composeErr) {
      console.error('[HugoDripReply] Draft compose failed:', composeErr.message);
      return res.json({
        success: true,
        intent: 'question',
        action: 'draft_failed',
        message: 'Reply classified as question but draft generation failed: ' + composeErr.message,
      });
    }
  } catch (err) {
    console.error('[HugoDripReply] Fatal error:', err.message);
    return res.status(500).json({ success: false, error: err.message });
  }
});

// ─── POST /api/hugo/drip/queue ────────────────────────────────────────────────
// Manually queue a lead for the drip sequence.
// Used by operators or auto-triggered when new leads are enriched.

router.post('/queue', requireAuth, async (req, res) => {
  const { leadId, email, operatorId } = req.body || {};

  if (!leadId || !email) {
    return res.status(400).json({ success: false, error: 'leadId and email required' });
  }

  // B2B filter
  const domain = (email.split('@')[1] || '').toLowerCase();
  const personalDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com'];
  if (personalDomains.includes(domain)) {
    return res.status(400).json({ success: false, error: 'Personal email addresses not eligible for drip' });
  }

  try {
    const now = new Date();

    // Queue Day 0, Day 3, Day 7
    const day3 = new Date(now); day3.setDate(day3.getDate() + 3);
    const day7 = new Date(now); day7.setDate(day7.getDate() + 7);

    await pool.query(
      `INSERT INTO hugo_drip_queue (lead_id, operator_id, target_send_date, drip_day, email_type, status)
       VALUES
         ($1, $2, CURRENT_DATE, 0, 'cold_drip_day0', 'pending'),
         ($1, $2, $3,          3, 'cold_drip_day3', 'pending'),
         ($1, $2, $4,          7, 'cold_drip_day7', 'pending')
       ON CONFLICT (lead_id, drip_day) DO NOTHING`,
      [parseInt(leadId, 10), req.userId, day3.toISOString().split('T')[0], day7.toISOString().split('T')[0]]
    );

    // Update lead drip status
    await pool.query(
      `UPDATE leads SET drip_status = 'queued', drip_operator_id = $1, drip_scheduled_at = NOW() WHERE id = $2`,
      [req.userId, parseInt(leadId, 10)]
    );

    console.log(`[HugoDripReply] Queued lead ${leadId} for drip sequence (Day 0/3/7)`);

    return res.json({
      success: true,
      message: `Lead queued for drip sequence (Day 0 → Day 3 → Day 7)`,
      schedule: {
        day_0: now.toISOString().split('T')[0],
        day_3: day3.toISOString().split('T')[0],
        day_7: day7.toISOString().split('T')[0],
      },
    });
  } catch (err) {
    console.error('[HugoDripReply] Queue error:', err.message);
    return res.status(500).json({ success: false, error: err.message });
  }
});

// ─── GET /api/hugo/drip/status/:leadId ────────────────────────────────────────
// Returns current drip status for a lead (for dashboard display)

router.get('/status/:leadId', requireAuth, async (req, res) => {
  const { leadId } = req.params;
  if (!leadId) return res.status(400).json({ success: false, error: 'leadId required' });

  try {
    const leadRows = await pool.query(
      `SELECT l.id, l.name, l.email, l.drip_status, l.drip_last_intent,
              l.drip_sent_day_0_at, l.drip_sent_day_3_at, l.drip_sent_day_7_at,
              l.drip_reply_classified_at
       FROM leads l WHERE l.id = $1`,
      [parseInt(leadId, 10)]
    );

    const queueRows = await pool.query(
      `SELECT drip_day, email_type, status, target_send_date, sent_at
       FROM hugo_drip_queue WHERE lead_id = $1 ORDER BY drip_day ASC`,
      [parseInt(leadId, 10)]
    );

    if (!leadRows.rows[0]) return res.status(404).json({ success: false, error: 'Lead not found' });

    return res.json({
      success: true,
      lead: leadRows.rows[0],
      queue: queueRows.rows,
    });
  } catch (err) {
    return res.status(500).json({ success: false, error: err.message });
  }
});

module.exports = router;